from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    count = {}
    result = []

    for number in numbers:
        if number in count:
            count[number] += 1
        else:
            count[number] = 1

    for number in numbers:
        if count[number] == 1:
            result.append(number)

    return result

